package testing

import (
	"testing"
)

func BenchmarkAllocsPerRun(b *testing.B) {
	b.Run("func call", func(b *testing.B) {
		b.SetBytes(int64(1 << 20))
		b.Cleanup(func() { b.Cleanup() })
		b.ResetTimer()
		AllocsPerRun(1, func() { b.Called() })
	})
}

func BenchmarkAllocsPerRun2(b *testing.B) {
	b.Run("func call", func(b *testing.B) {
		b.SetBytes(int64(1 << 20))
		b.Cleanup(func() { b.Cleanup() })
		b.ResetTimer()
		AllocsPerRun(100, func() { b.Called() })
	})
}

